    return spectrogram(waveform, this.window, 400, 160, {
      fft_length: 512,
      power: 2,
      center: false,
      preemphasis: 0.97,
      mel_filters: this.mel_filters,
      log_mel: "log",
      mel_floor: 0.0000001192092955078125,
      remove_dc_offset: true,
      max_num_frames: max_length,
      transpose: true
    });
